import dates from "@/lib/article-dates.json";

/**
 * When each guide was first published and last rewritten, and when each translation of it last
 * changed, all from git history.
 *
 * Generated by `npm run articles:dates` (also run before every build); see that script for why the
 * dates are read from commits rather than typed in. A guide with no entry yet (one added but not
 * committed) simply has no date, and the page omits it rather than showing a guess.
 */
type ArticleDates = { published: string; modified: string; locales?: Record<string, string> };
const table = dates as Record<string, ArticleDates>;

export const articleDates = (slug: string): { published: string; modified: string } | undefined => table[slug];

/** When this locale's translation of the guide last changed, if it has ever been committed. */
export const localeModified = (slug: string, locale: string): string | undefined => table[slug]?.locales?.[locale];

/** "18 August 2026" in English; the same date in the reader's own format elsewhere ("18. August 2026"). */
export function formatArticleDate(iso: string, intl = "en-GB"): string {
  return new Date(`${iso}T00:00:00Z`).toLocaleDateString(intl, { day: "numeric", month: "long", year: "numeric", timeZone: "UTC" });
}
